using System.Drawing;
using System.IO;
using System.Windows.Forms;

// Builds the full path to a file inside bin\Debug (chapter 2)
static class Files
{
    // The path to a file in the Data folder
    public static string Data(string fileName)
    {
        return Path.Combine(Application.StartupPath, "Data", fileName);
    }

    // The path to a picture in one of the Images folders
    public static string Image(string folder, string fileName)
    {
        return Path.Combine(Application.StartupPath, "Images", folder,
            fileName);
    }

    // The path to a sound in the Sounds folder
    public static string Sound(string fileName)
    {
        return Path.Combine(Application.StartupPath, "Sounds", fileName);
    }

    // Loads a picture, or gives null when the file is missing
    public static Image Picture(string folder, string fileName)
    {
        string path = Image(folder, fileName);
        if (!File.Exists(path)) return null;
        return System.Drawing.Image.FromFile(path);
    }
}

// Plays the game's sounds (chapter 2)
static class Sound
{
    public static bool Muted = false;
    private static SoundPlayer player = new SoundPlayer();

    // Plays one .wav file from the Sounds folder
    public static void Play(string fileName)
    {
        string path = Files.Sound(fileName);
        if (Muted || !File.Exists(path)) return;
        player.SoundLocation = path;
        player.Play();
    }
}

// Random orders and place names (chapter 2)
static class Mix
{
    private static Random random = new Random();

    // Gives the numbers 0 to count - 1 in a random order
    public static int[] ShuffledNumbers(int count)
    {
        int[] numbers = new int[count];
        for (int i = 0; i < count; i++) numbers[i] = i;
        for (int i = count - 1; i > 0; i--)
        {
            int j = random.Next(i + 1);
            int keep = numbers[i];
            numbers[i] = numbers[j];
            numbers[j] = keep;
        }
        return numbers;
    }

// 1 becomes "1st", 2 becomes "2nd", and so on
public static string Ordinal(int n)
{
    switch (n)
    {
        case 1: return "1st";
        case 2: return "2nd";
        case 3: return "3rd";
        default: return n + "th";
    }
}

